package com.dsaroadmap.controller;
import com.dsaroadmap.dto.ApiDtos.*;import com.dsaroadmap.model.Difficulty;import com.dsaroadmap.service.CatalogService;import java.util.*;import org.springframework.data.domain.Page;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api") public class CatalogController {private final CatalogService catalog;public CatalogController(CatalogService catalog){this.catalog=catalog;}@GetMapping("/concepts")List<ConceptSummary> concepts(){return catalog.concepts();}@GetMapping("/problems/{slug}")ProblemDetail problem(@PathVariable String slug){return catalog.problem(slug);}@GetMapping("/problems")Page<ProblemSummary> problems(@RequestParam(required=false)String query,@RequestParam(required=false)Difficulty difficulty,@RequestParam(required=false)String company,@RequestParam(required=false)String topic,@RequestParam(required=false)Integer maxMinutes,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(defaultValue="order")String sort){return catalog.problems(query,difficulty,company,topic,maxMinutes,page,size,sort);}@GetMapping("/search")List<SearchResult> search(@RequestParam String q){return catalog.search(q);}@GetMapping("/meta")Map<String,List<String>> meta(){return catalog.metadata();}}

